"""Predator attack contract: announced locked lunge, front contact, one hit and recovery."""
from pathlib import Path
import subprocess
ROOT=Path(__file__).resolve().parents[1]
program=r'''
const fs=require('fs'),vm=require('vm'),assert=require('assert'),context={Math,Set};vm.createContext(context);vm.runInContext(fs.readFileSync(process.argv[1]+'/src/predator-combat.js','utf8'),context);
const make=(targetZ=3)=>{context.p={x:0,z:targetZ,hp:100};context.localParty=[];context.journey={level:1,step:0,core:180};context.coreHits=0;context.classLine=()=>true;context.onJourneyHazard=h=>{context.journey.core-=h.damage*.65;context.coreHits++};context.distance=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);context.hazards=[];context.sounds=[];context.addHazard=(...a)=>context.hazards.push(a);context.playWorldSound=(...a)=>context.sounds.push(a);context.moveEntity=(a,x,z)=>{a.x+=x;a.z+=z};context.hurt=n=>context.p.hp-=n;context.canCommitMelee=()=>true;context.approachWarden=()=>{};return {x:0,z:0,timer:0,mode:'idle',root:{rotation:{y:0},position:{set(){}}}}};
for(const dt of [1/30,1/60,1/120]){const e=make();context.updatePredatorCombat(e,dt,context.p);assert(e.mode==='windup');assert(context.hazards.length===2&&context.hazards.every(h=>h[4]===0),'Telegraphs themselves cannot damage');const facing=e.lockAngle;context.p.x=3;for(let i=0;i<Math.ceil(.78/dt);i++)context.updatePredatorCombat(e,dt,context.p);assert(e.lockAngle===facing,'The announced line must not track a last-second dodge');context.p.x=0;for(let i=0;i<Math.ceil(.33/dt)+1;i++)context.updatePredatorCombat(e,dt,context.p);assert(Math.abs(e.z-2.4)<1e-8,'Lunge distance must be independent of simulation step');assert(context.p.hp===78,'One damage event per player');assert(e.mode==='recover');for(let i=0;i<3;i++)context.updatePredatorCombat(e,dt,context.p);assert(context.p.hp===78,'Recovery cannot damage');}
const e=make();context.updatePredatorCombat(e,.01,context.p);context.p.x=3;for(let i=0;i<120;i++)context.updatePredatorCombat(e,.01,context.p);assert(context.p.hp===100,'Leaving the locked lane must avoid the hit');
const wall=make();context.updatePredatorCombat(wall,.01,context.p);context.moveEntity=()=>{};for(let i=0;i<100;i++)context.updatePredatorCombat(wall,.01,context.p);assert(wall.mode==='recover'&&wall.z===0,'Solid wall must stop lunge and produce recovery');
// A heart saboteur contacts the core's surface once, even though the lane markers have zero damage.
for(const dt of [1/30,1/60,1/120]){const core=make();core.z=-76.9;core.sabotage=true;context.journey={level:3,step:4,core:180};context.p={x:20,z:-73,hp:100};const target={x:0,z:-73};context.moveEntity=(a,x,z)=>{a.x+=x;a.z=Math.min(-74.6,a.z+z)};for(let i=0;i<Math.ceil(1.3/dt);i++)context.updatePredatorCombat(core,dt,target);assert(context.coreHits===1&&Math.abs(context.journey.core-165.7)<1e-8,'Frontal core contact must preserve one sabotage hit');assert(context.p.hp===100,'A distant player must not be hit by core contact');assert(context.hazards.every(h=>h[4]===0),'Core damage must not turn lane markers back into area attacks');}
const blockedCore=make();blockedCore.z=-74.65;blockedCore.sabotage=true;context.journey={level:3,step:4,core:180};context.p={x:20,z:-73,hp:100};context.moveEntity=()=>{};context.classLine=()=>false;for(let i=0;i<120;i++)context.updatePredatorCombat(blockedCore,.01,{x:0,z:-73});assert(context.coreHits===0&&context.journey.core===180,'An intervening wall blocks a nearby core contact');
const distantCore=make();distantCore.z=-77.5;distantCore.sabotage=true;context.journey={level:3,step:4,core:180};context.p={x:20,z:-73,hp:100};for(let i=0;i<120;i++)context.updatePredatorCombat(distantCore,.01,{x:0,z:-73});assert(context.coreHits===0,'An out-of-reach core must stay intact');
const sideCore=make();sideCore.z=-74.65;sideCore.sabotage=true;context.journey={level:3,step:4,core:180};context.p={x:20,z:-73,hp:100};context.beginPredatorAttack(sideCore,{x:4,z:sideCore.z});context.moveEntity=()=>{};for(let i=0;i<120;i++)context.updatePredatorCombat(sideCore,.01,{x:0,z:-73});assert(context.coreHits===0,'The core must remain outside a side-facing locked lunge');
console.log('PASS: locked frontal telegraph, no circular damage, fixed lunge at30/60/120Hz, single player/core contact, dodgeable lane, wall stop, core range/direction and recovery.');
'''
subprocess.run(['node','-e',program,str(ROOT)],check=True)
